create table public.audio_progress(user_id uuid not null references public.profiles(id),audio_id uuid not null references public.audio_briefs(id) on delete cascade,position_seconds double precision not null default 0 check(position_seconds>=0 and position_seconds<=7200),playback_rate double precision not null default 1 check(playback_rate between 0.5 and 2),updated_at timestamptz not null default now(),primary key(user_id,audio_id));
alter table public.audio_progress enable row level security;
revoke all on public.audio_progress from public,anon,authenticated;grant select,insert,update,delete on public.audio_progress to authenticated;grant all on public.audio_progress to service_role;
create policy owner_audio_progress on public.audio_progress for all to authenticated using((select public.is_owner()) and user_id=(select auth.uid())) with check((select public.is_owner()) and user_id=(select auth.uid()) and exists(select 1 from public.audio_briefs b where b.id=audio_id and b.owner_id=(select auth.uid())));
